mapper.select:
SELECT r.id, r.expert_id, r.user_id, p.real_name AS expert_name, COALESCE(u.nickname, u.username) AS user_name, r.rating, r.content, r.create_time, r.update_time FROM `expert_review` r INNER JOIN `expert_profile` p ON p.id = r.expert_id LEFT JOIN `user` u ON u.id = r.user_id
AND p.audit_status = 2
AND r.expert_id = #{expertId}
AND p.real_name LIKE CONCAT('%', #{expertName}, '%')
AND r.user_id = #{userId}
AND ( u.nickname LIKE CONCAT('%', #{userName}, '%') OR u.username LIKE CONCAT('%', #{userName}, '%') )
AND r.create_time >= #{startTime}
AND r.create_time <= #{endTime}
ORDER BY r.id DESC
